(() => {
  'use strict';

  const Store = window.FestacolSessionStore;
  const Data = window.FestacolQuestionData;
  const Engine = window.FestacolAssessmentEngine;
  const Proctor = window.FestacolProctorPolicy;
  const QR = window.FestacolQR;
  const root = document.getElementById('admin-root');
  const dialog = document.getElementById('admin-dialog');
  const dialogContent = document.getElementById('admin-dialog-content');
  const mobileNavDialog = document.getElementById('mobile-nav-dialog');
  const alertHost = document.getElementById('admin-alert');
  const breadcrumb = document.getElementById('admin-breadcrumb');
  const pageLabel = document.getElementById('admin-page-label');
  const toastStack = document.getElementById('toast-stack');
  if (!Store || !Data || !Engine || !Proctor || !QR || !root || !dialog) throw new Error('Festacol admin dependencies are unavailable.');

  const esc = (value) => String(value ?? '')
    .replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;').replaceAll("'", '&#039;');
  const qs = () => new URL(location.href).searchParams;
  const icon = (path, cls = 'size-5 shrink-0') => `<svg class="${cls}" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="${path}" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
  const I = Object.freeze({
    home:'M4 10.5 12 4l8 6.5V20H4v-9.5ZM9.5 20v-6h5v6', users:'M16 20v-1.5a4.5 4.5 0 0 0-4.5-4.5h-3A4.5 4.5 0 0 0 4 18.5V20m6-10a3 3 0 1 0 0-6 3 3 0 0 0 0 6Zm7 1a2.5 2.5 0 1 0 0-5m3 14v-1a4 4 0 0 0-3-3.87',
    exam:'M7 3h10a2 2 0 0 1 2 2v16H5V5a2 2 0 0 1 2-2Zm2 5h6M9 12h6m-6 4h4', classes:'M4 20h16M6 20v-9h12v9M8 11V7l4-3 4 3v4', question:'M9.5 9a2.5 2.5 0 1 1 4 2c-1 .75-1.5 1.25-1.5 2.5M12 17h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',
    report:'M5 20V10m5 10V5m5 15v-7m4 7H3', settings:'M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7Zm7-3.5 2-1-2-3-2 .5-1.5-1L15 5h-6l-.5 2.5-1.5 1L5 8l-2 3 2 1-.1 2L3 15l2 3 2-.5 1.5 1L9 21h6l.5-2.5 1.5-1 2 .5 2-3-2-1 .1-2Z',
    plus:'M12 5v14M5 12h14', close:'M6 18 18 6M6 6l12 12', more:'M5 12h.01M12 12h.01M19 12h.01', arrow:'M5 12h14m-6-6 6 6-6 6', back:'M19 12H5m6-6-6 6 6 6', qr:'M4 4h6v6H4V4Zm10 0h6v6h-6V4ZM4 14h6v6H4v-6Zm11 1h2v2h-2v-2Zm3-1h2v2h-2v-2Zm0 4h2v2h-2v-2Zm-4 0h2v2h-2v-2Z',
    shield:'m9 12 2 2 4-4m4-4-7-3-7 3v5c0 4.5 2.9 8 7 10 4.1-2 7-5.5 7-10V6Z', camera:'M14.5 9.5 19 7v10l-4.5-2.5M6 6h7a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2Z',
    whatsapp:'M20 11.5a8 8 0 0 1-11.7 7.1L4 20l1.4-4.2A8 8 0 1 1 20 11.5Z', edit:'M4 20h4l11-11-4-4L4 16v4Zm9-13 4 4', trash:'M5 7h14m-9-3h4l1 3H9l1-3Zm-3 3 1 13h8l1-13M10 11v6m4-6v6',
    search:'m21 21-4.35-4.35m2.35-5.65a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z', refresh:'M20 7v5h-5M4 17v-5h5m9.5-3A7 7 0 0 0 6 7m-.5 8A7 7 0 0 0 18 17', check:'m5 12 4 4L19 6', warning:'M12 9v4m0 4h.01M10.3 3.9 2 18h19.4L13.7 3.9a2 2 0 0 0-3.4 0Z'
  });

  const ROUTES = Object.freeze([
    ['overview','Overview',I.home],['users','Students & staff',I.users],['exams','Exams',I.exam],['classes','Classes',I.classes],['questions','Question bank',I.question],['reports','Reports',I.report],['settings','Settings',I.settings]
  ]);
  const ROUTE_MAP = Object.fromEntries(ROUTES.map(([key,label]) => [key,label]));
  const MODES = Object.freeze({ qualifier:'Placement qualifier', mixed:'Mixed subjects', single:'Single subject', waec:'WAEC practice' });
  const btnPrimary = 'inline-flex min-h-10 items-center justify-center gap-2 rounded-lg bg-black px-4 py-2 text-sm font-semibold text-white hover:bg-neutral-800 focus:outline-none focus:ring-4 focus:ring-neutral-300 disabled:cursor-not-allowed disabled:opacity-40';
  const btnSecondary = 'inline-flex min-h-10 items-center justify-center gap-2 rounded-lg border border-neutral-300 bg-white px-4 py-2 text-sm font-semibold text-neutral-900 hover:bg-neutral-100 focus:outline-none focus:ring-4 focus:ring-neutral-200 disabled:cursor-not-allowed disabled:opacity-40';
  const btnDanger = 'inline-flex min-h-10 items-center justify-center gap-2 rounded-lg bg-red-700 px-4 py-2 text-sm font-semibold text-white hover:bg-red-800 focus:outline-none focus:ring-4 focus:ring-red-200 disabled:cursor-not-allowed disabled:opacity-40';
  const iconBtn = 'inline-flex size-10 items-center justify-center rounded-lg border border-neutral-300 bg-white text-neutral-700 hover:bg-neutral-100 hover:text-black focus:outline-none focus:ring-4 focus:ring-neutral-200';
  const field = 'block min-h-11 w-full rounded-lg border border-neutral-300 bg-white px-3 py-2.5 text-sm text-neutral-950 placeholder:text-neutral-400 focus:border-black focus:ring-black';
  const label = 'text-sm font-semibold text-neutral-800';
  const card = 'rounded-2xl border border-neutral-200 bg-white shadow-sm';

  let data = null;
  let userHashes = new Map();
  let wizard = null;
  let lastFocus = null;

  const currentPage = () => ROUTE_MAP[qs().get('page')] ? qs().get('page') : 'overview';
  const href = (page, extra = {}) => {
    const url = new URL('./admin.html', location.href); url.search = ''; url.searchParams.set('page', page);
    Object.entries(extra).forEach(([key,value]) => { if (value !== undefined && value !== null && value !== '') url.searchParams.set(key, String(value)); });
    return `${url.pathname.split('/').pop()}${url.search}`;
  };
  const navigate = (page, extra = {}, replace = false) => { history[replace ? 'replaceState' : 'pushState']({}, '', href(page, extra)); render(); };
  const sessionState = (session) => {
    if (!session) return 'missing'; const now = Date.now(); if (session.status !== 'open') return session.status;
    if (session.startsAt && now < Number(session.startsAt)) return 'scheduled'; if (session.endsAt && now >= Number(session.endsAt)) return 'closed'; return 'open';
  };
  const formatDate = (timestamp) => timestamp ? new Intl.DateTimeFormat('en-NG',{dateStyle:'medium',timeStyle:'short'}).format(new Date(timestamp)) : 'Not scheduled';
  const coverage = (session) => session.mode === 'qualifier' ? 'Placement domains' : session.subjects.map((code) => Data.subjectByCode(data, code)?.label || code).join(', ');
  const tone = (status) => ['open','active','submitted','on-track'].includes(status) ? 'emerald' : ['scheduled'].includes(status) ? 'blue' : ['draft','review','in-progress'].includes(status) ? 'amber' : ['closed','inactive','graduating'].includes(status) ? 'neutral' : 'red';
  const badge = (text, explicitTone = tone(String(text).toLowerCase())) => `<span class="inline-flex items-center rounded-full border px-2.5 py-1 text-xs font-semibold ${explicitTone === 'emerald' ? 'border-emerald-200 bg-emerald-50 text-emerald-800' : explicitTone === 'amber' ? 'border-amber-200 bg-amber-50 text-amber-800' : explicitTone === 'red' ? 'border-red-200 bg-red-50 text-red-800' : explicitTone === 'blue' ? 'border-blue-200 bg-blue-50 text-blue-800' : 'border-neutral-200 bg-neutral-100 text-neutral-700'}">${esc(text)}</span>`;
  const initials = (name) => String(name || '?').split(/\s+/u).slice(0,2).map((part) => part[0]).join('').toUpperCase();
  const mean = (values) => values.length ? Math.round(values.reduce((sum,value) => sum + (Number(value) || 0), 0) / values.length) : 0;
  const classFor = (classId) => Store.listClasses().find((item) => item.id === classId);
  const pageHead = (eyebrow,title,detail,actions='') => `<div class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div class="max-w-3xl"><p class="text-xs font-bold uppercase tracking-[.14em] text-neutral-500">${esc(eyebrow)}</p><h2 class="mt-2 font-display text-2xl font-extrabold tracking-tight sm:text-3xl">${esc(title)}</h2><p class="mt-2 max-w-2xl text-sm leading-6 text-neutral-600">${esc(detail)}</p></div>${actions ? `<div class="flex shrink-0 flex-wrap gap-2">${actions}</div>` : ''}</div>`;
  const empty = (title,detail,action='') => `<div class="grid min-h-56 place-items-center p-7 text-center"><div class="max-w-md"><span class="mx-auto grid size-12 place-items-center rounded-xl bg-neutral-100 text-neutral-500">${icon(I.question)}</span><h3 class="mt-4 font-display text-lg font-extrabold">${esc(title)}</h3><p class="mt-2 text-sm leading-6 text-neutral-500">${esc(detail)}</p>${action ? `<div class="mt-5">${action}</div>` : ''}</div></div>`;
  const metric = (labelText,value,detail) => `<article class="${card} p-5"><p class="text-xs font-bold uppercase tracking-[.12em] text-neutral-500">${esc(labelText)}</p><strong class="mt-3 block font-display text-3xl font-extrabold tracking-tight">${esc(value)}</strong><p class="mt-2 text-xs leading-5 text-neutral-500">${esc(detail)}</p></article>`;
  const alertMarkup = (message,kind='info') => `<div class="flex items-start gap-3 rounded-xl border p-4 text-sm ${kind==='danger'?'border-red-200 bg-red-50 text-red-900':kind==='warning'?'border-amber-200 bg-amber-50 text-amber-900':kind==='success'?'border-emerald-200 bg-emerald-50 text-emerald-900':'border-neutral-200 bg-neutral-50 text-neutral-800'}">${icon(kind==='success'?I.check:kind==='danger'||kind==='warning'?I.warning:I.shield)}<span class="leading-6">${esc(message)}</span></div>`;

  const toast = (message, kind='info') => {
    const node = document.createElement('div'); node.className = `pointer-events-auto flex items-start gap-3 rounded-xl border bg-white p-4 shadow-lg ${kind==='danger'?'border-red-200':kind==='success'?'border-emerald-200':'border-neutral-200'}`;
    node.innerHTML = `<span class="mt-0.5 grid size-7 shrink-0 place-items-center rounded-full ${kind==='success'?'bg-emerald-100 text-emerald-700':kind==='danger'?'bg-red-100 text-red-700':'bg-neutral-100 text-neutral-700'}">${icon(kind==='success'?I.check:kind==='danger'?I.warning:I.shield,'size-4')}</span><div class="min-w-0 flex-1"><strong class="text-sm">${kind==='danger'?'Action needed':kind==='success'?'Updated':'Festacol'}</strong><p class="mt-1 text-xs leading-5 text-neutral-600">${esc(message)}</p></div><button class="rounded-md p-1 hover:bg-neutral-100" data-toast-close aria-label="Dismiss">${icon(I.close,'size-4')}</button>`;
    toastStack.append(node); setTimeout(() => node.remove(), 4500);
  };
  const announce = (message, kind='danger') => { alertHost.className='mx-auto max-w-[1600px] px-4 pt-4 sm:px-6 lg:px-8'; alertHost.innerHTML=alertMarkup(message,kind); };

  const openDialog = (content, maxWidth='max-w-4xl') => {
    lastFocus = document.activeElement; dialog.className = `w-[calc(100%_-_1.5rem)] ${maxWidth} rounded-2xl border border-neutral-200 bg-white p-0 shadow-2xl backdrop:bg-black/45 sm:w-[calc(100%_-_3rem)]`;
    dialogContent.innerHTML = content; if (!dialog.open) dialog.showModal(); queueMicrotask(() => dialog.querySelector('button,input,select,textarea,[href]')?.focus()); window.initFlowbite?.();
  };
  const closeDialog = () => { if (dialog.open) dialog.close(); dialogContent.innerHTML=''; lastFocus?.focus?.(); };
  const modalHeader = (eyebrow,title,detail='') => `<div class="sticky top-0 z-10 flex items-start gap-4 border-b border-neutral-200 bg-white/95 px-5 py-4 backdrop-blur-xl sm:px-6"><div class="min-w-0 flex-1"><p class="text-xs font-bold uppercase tracking-[.14em] text-neutral-500">${esc(eyebrow)}</p><h2 id="admin-dialog-title" class="mt-1 font-display text-xl font-extrabold sm:text-2xl">${esc(title)}</h2>${detail?`<p class="mt-1 text-xs leading-5 text-neutral-500">${esc(detail)}</p>`:''}</div><button type="button" class="${iconBtn}" data-close-dialog aria-label="Close dialog">${icon(I.close)}</button></div>`;
  const confirmDialog = ({title,detail,confirm='Confirm',danger=false,onConfirm}) => {
    openDialog(`${modalHeader('Confirmation',title,detail)}<div class="p-5 sm:p-6">${danger?alertMarkup('This action changes stored academic records. Review the details before continuing.','warning'):''}<div class="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><button type="button" class="${btnSecondary}" data-close-dialog>Cancel</button><button type="button" class="${danger?btnDanger:btnPrimary}" data-confirm-action>${esc(confirm)}</button></div></div>`,'max-w-xl');
    dialog.querySelector('[data-confirm-action]').addEventListener('click', async () => { try { await onConfirm(); closeDialog(); } catch (error) { toast(error.message,'danger'); } }, { once:true });
  };

  const directExamLink = (session) => Proctor.decorateStudentLink(Store.getSessionLink(session, location.href), Proctor.getAdminPolicy(session.id).cameraRequired);
  const renderQr = (selector, value) => queueMicrotask(() => { const host = document.querySelector(selector); if (host) QR.render(host, value); });
  const examIdLabel = (session) => `<div class="rounded-xl border border-neutral-200 bg-neutral-50 p-4"><span class="text-[11px] font-bold uppercase tracking-[.14em] text-neutral-500">Exam ID</span><strong class="mt-1 block font-mono text-xl tracking-[.12em] text-neutral-950">${esc(session.id)}</strong><p class="mt-1 text-xs text-neutral-500">Students can enter this ID manually if they cannot scan the QR code.</p></div>`;

  async function hydrateUserHashes() {
    const entries = await Promise.all(Store.listUsers().filter((user) => user.role === 'student').map(async (user) => [user.id, await Engine.studentHash(user.firstName, user.lastName)]));
    userHashes = new Map(entries);
  }
  const attemptsForUser = (user) => { const hash = userHashes.get(user.id); return hash ? Store.attemptsForStudent(hash) : []; };

  function renderNav() {
    const markup = ROUTES.map(([key,name,path]) => `<a href="${href(key)}" data-admin-route="${key}" class="flex min-h-11 items-center gap-3 rounded-lg px-3 text-sm font-semibold text-neutral-600 hover:bg-neutral-100 hover:text-black focus:outline-none focus:ring-4 focus:ring-neutral-200 aria-[current=page]:bg-black aria-[current=page]:text-white">${icon(path)}<span>${esc(name)}</span></a>`).join('');
    document.getElementById('desktop-nav').innerHTML = markup; document.getElementById('mobile-nav').innerHTML = markup;
  }
  function chrome(page) {
    breadcrumb.textContent = `Administration / ${ROUTE_MAP[page]}`; pageLabel.textContent = ROUTE_MAP[page];
    document.querySelectorAll('[data-admin-route]').forEach((link) => link.dataset.adminRoute === page ? link.setAttribute('aria-current','page') : link.removeAttribute('aria-current'));
  }

  function overviewPage() {
    const users=Store.listUsers(), classes=Store.listClasses(), sessions=Store.listSessions(), attempts=Store.getAttempts();
    const students=users.filter((u)=>u.role==='student'), active=sessions.filter((s)=>sessionState(s)==='open'), submitted=attempts.filter((a)=>a.submittedAt&&!a.rewriteArchivedAt);
    const recent=[...attempts].sort((a,b)=>(b.submittedAt||b.startedAt||0)-(a.submittedAt||a.startedAt||0)).slice(0,6);
    root.innerHTML=`${pageHead('Academic operations','Administration overview','A single operating view for students, classes, examination delivery and integrity records.',`<button class="${btnPrimary}" data-open-exam-wizard>${icon(I.plus,'size-4')} Create exam</button>`)}
      <section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">${metric('Students',students.length,`${students.filter(u=>u.status==='active').length} active records`)}${metric('Classes',classes.filter(c=>c.status==='active').length,'SS1–SS3 academic groups')}${metric('Live exams',active.length,`${sessions.length} configured sessions`)}${metric('Submitted',submitted.length,`${attempts.filter(a=>a.startedAt&&!a.submittedAt).length} currently in progress`)}</section>
      <div class="mt-5 grid gap-5 xl:grid-cols-[1.45fr_.75fr]"><section class="${card} overflow-hidden"><div class="flex items-center justify-between border-b border-neutral-200 px-5 py-4"><div><p class="text-xs font-bold uppercase tracking-[.12em] text-neutral-500">Recent activity</p><h3 class="mt-1 font-display text-lg font-extrabold">Candidate attempts</h3></div><a href="${href('reports',{view:'students'})}" class="${btnSecondary}">Reports</a></div>${recent.length?`<div class="divide-y divide-neutral-100">${recent.map((a)=>`<button class="flex w-full items-center gap-3 p-4 text-left hover:bg-neutral-50" data-attempt-detail="${esc(a.attemptHash)}"><span class="grid size-10 shrink-0 place-items-center rounded-xl bg-neutral-100 text-xs font-extrabold">${esc(initials(a.studentName))}</span><span class="min-w-0 flex-1"><strong class="block truncate text-sm">${esc(a.studentName||'Candidate')}</strong><span class="mt-1 block truncate text-xs text-neutral-500">${esc(a.sessionTitle)} · ${a.submittedAt?`Submitted ${a.score??0}%`:'In progress'}</span></span>${badge(a.rewriteArchivedAt?'previous':a.submittedAt?'submitted':'in progress',a.rewriteArchivedAt?'neutral':a.submittedAt?'emerald':'amber')}</button>`).join('')}</div>`:empty('No candidate activity','Attempts will appear here when students start an examination.')}</section>
      <aside class="${card} p-5"><p class="text-xs font-bold uppercase tracking-[.12em] text-neutral-500">Operations queue</p><h3 class="mt-1 font-display text-lg font-extrabold">Needs attention</h3><div class="mt-4 grid gap-3">${alertMarkup(`${sessions.filter(s=>s.status==='draft').length} draft exam(s) are not visible to candidates.`,'warning')}${alertMarkup(`${attempts.filter(a=>a.startedAt&&!a.submittedAt).length} candidate attempt(s) are still active.`,'info')}${alertMarkup(`${Store.listWhatsAppGroups().length} class WhatsApp group(s) have QR access configured.`,'success')}</div></aside></div>`;
  }

  const responsiveTable = (headers, rows, cards) => `<div class="hidden overflow-x-auto md:block"><table class="w-full text-left text-sm"><thead class="border-b border-neutral-200 bg-neutral-50 text-[11px] font-bold uppercase tracking-[.1em] text-neutral-500"><tr>${headers.map((h)=>`<th class="whitespace-nowrap px-4 py-3">${esc(h)}</th>`).join('')}</tr></thead><tbody class="divide-y divide-neutral-100">${rows}</tbody></table></div><div class="divide-y divide-neutral-100 md:hidden">${cards}</div>`;

  function usersPage() {
    const role = ['all','student','teacher','administrator'].includes(qs().get('role')) ? qs().get('role') : 'all';
    const search = String(qs().get('q')||'').trim().toLowerCase();
    const users=Store.listUsers().filter((u)=>(role==='all'||u.role===role)&&(!search||`${u.fullName} ${u.id}`.toLowerCase().includes(search)));
    const rows=users.map((u)=>{const cls=classFor(u.classId),ats=attemptsForUser(u);return`<tr class="hover:bg-neutral-50"><td class="px-4 py-3"><button class="flex items-center gap-3 text-left" data-user-detail="${esc(u.id)}"><span class="grid size-9 place-items-center rounded-lg bg-neutral-100 text-xs font-bold">${esc(initials(u.fullName))}</span><span><strong class="block">${esc(u.fullName)}</strong><span class="text-xs text-neutral-500">${esc(u.id)}</span></span></button></td><td class="px-4 py-3 capitalize">${esc(u.role)}</td><td class="px-4 py-3">${esc(cls?.name||'—')}</td><td class="px-4 py-3">${ats.length}</td><td class="px-4 py-3">${badge(u.status)}</td><td class="px-4 py-3 text-right"><button class="${iconBtn}" data-user-detail="${esc(u.id)}" aria-label="Open ${esc(u.fullName)}">${icon(I.more)}</button></td></tr>`}).join('');
    const cards=users.map((u)=>`<button class="flex w-full items-center gap-3 p-4 text-left hover:bg-neutral-50" data-user-detail="${esc(u.id)}"><span class="grid size-10 shrink-0 place-items-center rounded-xl bg-neutral-100 text-xs font-bold">${esc(initials(u.fullName))}</span><span class="min-w-0 flex-1"><strong class="block truncate text-sm">${esc(u.fullName)}</strong><span class="mt-1 block text-xs text-neutral-500">${esc(classFor(u.classId)?.name||u.role)}</span></span>${badge(u.status)}</button>`).join('');
    root.innerHTML=`${pageHead('Directory','Students & staff','Student records open into exam history and integrity activity using the stored student identity—not display-name matching.',`<button class="${btnPrimary}" data-user-create>${icon(I.plus,'size-4')} Add user</button>`)}
      <div class="mb-4 grid gap-3 md:grid-cols-[minmax(0,1fr)_auto]"><label class="relative"><span class="sr-only">Search users</span><span class="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-neutral-400">${icon(I.search,'size-4')}</span><input id="user-search" class="${field} pl-9" value="${esc(qs().get('q')||'')}" placeholder="Search name or student ID"></label><div class="flex overflow-x-auto rounded-lg border border-neutral-300 bg-white p-1">${['all','student','teacher','administrator'].map((item)=>`<button class="min-h-9 whitespace-nowrap rounded-md px-3 text-xs font-semibold ${role===item?'bg-black text-white':'text-neutral-600 hover:bg-neutral-100'}" data-user-role="${item}">${item==='all'?'All roles':item}</button>`).join('')}</div></div>
      <section class="${card} overflow-hidden">${users.length?responsiveTable(['User','Role','Class','Exam attempts','Status',''],rows,cards):empty('No matching users','Change the search or role filter.')}</section>`;
  }

  function examTableRows(sessions) {
    const rows=sessions.map((s)=>{const ats=Store.attemptsForSession(s.id),submitted=ats.filter(a=>a.submittedAt&&!a.rewriteArchivedAt);return`<tr class="hover:bg-neutral-50"><td class="px-4 py-3"><button class="text-left" data-exam-detail="${esc(s.id)}"><strong class="block max-w-sm">${esc(s.title)}</strong><span class="mt-1 block font-mono text-[11px] tracking-wider text-neutral-500">${esc(s.id)}</span></button></td><td class="px-4 py-3"><span class="block text-xs font-semibold">${esc(s.classLevel)} · ${esc(s.classGroup)}</span><span class="mt-1 block max-w-xs text-xs text-neutral-500">${esc(coverage(s))}</span></td><td class="px-4 py-3"><strong>${s.questionCount}</strong><span class="block text-xs text-neutral-500">${esc(Store.durationLabel(s.durationSeconds))}</span></td><td class="px-4 py-3"><strong>${ats.length}</strong><span class="block text-xs text-neutral-500">${submitted.length} submitted</span></td><td class="px-4 py-3">${badge(sessionState(s))}</td><td class="px-4 py-3 text-right"><button class="${iconBtn}" data-exam-detail="${esc(s.id)}" aria-label="Manage ${esc(s.title)}">${icon(I.more)}</button></td></tr>`}).join('');
    const cards=sessions.map((s)=>{const ats=Store.attemptsForSession(s.id);return`<button class="w-full p-4 text-left hover:bg-neutral-50" data-exam-detail="${esc(s.id)}"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><strong class="block truncate text-sm">${esc(s.title)}</strong><span class="mt-1 block font-mono text-[11px] tracking-wider text-neutral-500">${esc(s.id)}</span></div>${badge(sessionState(s))}</div><div class="mt-3 grid grid-cols-3 gap-2 text-xs text-neutral-600"><span>${s.questionCount} Q</span><span>${esc(Store.durationLabel(s.durationSeconds))}</span><span>${ats.length} attempts</span></div></button>`}).join('');
    return responsiveTable(['Exam','Audience','Paper','Attempts','Status',''],rows,cards);
  }
  function examsPage() {
    const status=['all','open','scheduled','draft','closed'].includes(qs().get('status'))?qs().get('status'):'all';
    const all=Store.listSessions(),sessions=status==='all'?all:all.filter(s=>sessionState(s)===status),ats=Store.getAttempts();
    root.innerHTML=`${pageHead('Assessment operations','Exams','Create, distribute, update and audit examinations without exposing raw candidate URLs.',`<button class="${btnPrimary}" data-open-exam-wizard>${icon(I.plus,'size-4')} Create exam</button>`)}
      <section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">${metric('Sessions',all.length,'all configured examinations')}${metric('Live',all.filter(s=>sessionState(s)==='open').length,'currently open')}${metric('Submitted',ats.filter(a=>a.submittedAt&&!a.rewriteArchivedAt).length,'current submitted attempts')}${metric('Integrity events',ats.reduce((n,a)=>n+(a.integrityEvents?.length||0),0),'attached to exam attempts')}</section>
      <section class="${card} mt-5 overflow-hidden"><div class="flex flex-col gap-3 border-b border-neutral-200 p-4 sm:flex-row sm:items-center sm:justify-between"><div class="flex overflow-x-auto rounded-lg border border-neutral-300 bg-white p-1">${['all','open','scheduled','draft','closed'].map((item)=>`<button class="min-h-9 whitespace-nowrap rounded-md px-3 text-xs font-semibold ${status===item?'bg-black text-white':'text-neutral-600 hover:bg-neutral-100'}" data-exam-status="${item}">${item}</button>`).join('')}</div><span class="text-xs font-semibold text-neutral-500">${sessions.length} shown</span></div>${sessions.length?examTableRows(sessions):empty('No exams in this view','Change the filter or create a new examination.')}</section>`;
  }

  function classesPage() {
    const classes=Store.listClasses(),users=Store.listUsers(),groups=Store.listWhatsAppGroups();
    root.innerHTML=`${pageHead('Academic structure','Classes & communication','Manage class groups and attach one parent/student WhatsApp group to the intended class.',`<button class="${btnPrimary}" data-class-create>${icon(I.plus,'size-4')} New class</button><button class="${btnSecondary}" data-whatsapp-create>${icon(I.whatsapp,'size-4')} Add WhatsApp group</button>`)}
      <div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3">${classes.filter(c=>c.status==='active').map((cls)=>{const students=users.filter(u=>u.role==='student'&&u.classId===cls.id),group=groups.find(g=>g.classId===cls.id);return`<article class="${card} p-5"><div class="flex items-start justify-between gap-3"><div><span class="text-xs font-bold uppercase tracking-[.12em] text-neutral-500">${esc(cls.classLevel)} · ${esc(cls.stream)}</span><h3 class="mt-2 font-display text-lg font-extrabold">${esc(cls.name)}</h3><p class="mt-1 text-xs text-neutral-500">${esc(cls.room||'Room not assigned')}</p></div><button class="${iconBtn}" data-class-detail="${esc(cls.id)}" aria-label="Manage ${esc(cls.name)}">${icon(I.more)}</button></div><div class="mt-4 grid grid-cols-2 gap-2"><div class="rounded-xl bg-neutral-50 p-3"><span class="text-xs text-neutral-500">Students</span><strong class="mt-1 block">${students.length}/${cls.capacity}</strong></div><div class="rounded-xl bg-neutral-50 p-3"><span class="text-xs text-neutral-500">WhatsApp</span><strong class="mt-1 block text-sm">${group?'Connected':'Not set'}</strong></div></div>${group?`<button class="mt-4 flex w-full items-center gap-2 rounded-xl border border-neutral-200 p-3 text-left text-xs font-semibold hover:bg-neutral-50" data-whatsapp-edit="${esc(group.id)}">${icon(I.whatsapp,'size-4')} ${esc(group.name)}</button>`:''}</article>`}).join('')}</div>
      <section class="${card} mt-6 overflow-hidden"><div class="flex items-center justify-between border-b border-neutral-200 p-5"><div><p class="text-xs font-bold uppercase tracking-[.12em] text-neutral-500">WhatsApp group management</p><h3 class="mt-1 font-display text-lg font-extrabold">Class group QR board</h3></div><button class="${btnSecondary}" data-whatsapp-create>${icon(I.plus,'size-4')} Add group</button></div>${groups.length?responsiveTable(['Group','Class','Updated',''],groups.map(g=>`<tr><td class="px-4 py-3"><strong>${esc(g.name)}</strong></td><td class="px-4 py-3">${esc(classFor(g.classId)?.name||'Unassigned')}</td><td class="px-4 py-3 text-xs text-neutral-500">${esc(formatDate(g.updatedAt))}</td><td class="px-4 py-3 text-right"><button class="${iconBtn}" data-whatsapp-edit="${esc(g.id)}">${icon(I.qr)}</button></td></tr>`).join(''),groups.map(g=>`<button class="flex w-full items-center gap-3 p-4 text-left" data-whatsapp-edit="${esc(g.id)}"><span class="grid size-10 place-items-center rounded-xl bg-neutral-100">${icon(I.whatsapp,'size-4')}</span><span class="min-w-0 flex-1"><strong class="block truncate text-sm">${esc(g.name)}</strong><span class="text-xs text-neutral-500">${esc(classFor(g.classId)?.name||'Unassigned')}</span></span>${icon(I.qr,'size-4')}</button>`).join('')):empty('No WhatsApp groups yet','Add a group invite link and associate it with a class; Festacol will generate the QR locally.')}</section>`;
  }

  function questionsPage() {
    const subject=qs().get('subject')||'all',type=qs().get('type')||'all';
    const questions=data.questions.filter(q=>(subject==='all'||q.subjectCode===subject)&&(type==='all'||q.type===type));
    const rows=questions.slice(0,120).map(q=>`<tr class="hover:bg-neutral-50"><td class="max-w-xl px-4 py-3"><button class="text-left" data-question-detail="${q.id}"><strong class="line-clamp-2">${esc(q.prompt)}</strong><span class="mt-1 block text-xs text-neutral-500">#${q.id}${q.custom?' · Custom':''}</span></button></td><td class="px-4 py-3">${esc(q.subject)}</td><td class="px-4 py-3">${q.levels.map(x=>badge(x,'neutral')).join(' ')}</td><td class="px-4 py-3">${badge(q.type,'neutral')}</td><td class="px-4 py-3 text-right"><button class="${iconBtn}" data-question-detail="${q.id}">${icon(I.more)}</button></td></tr>`).join('');
    const cards=questions.slice(0,120).map(q=>`<button class="w-full p-4 text-left" data-question-detail="${q.id}"><strong class="line-clamp-2 text-sm">${esc(q.prompt)}</strong><span class="mt-2 flex items-center gap-2 text-xs text-neutral-500">${esc(q.subject)} ${badge(q.type,'neutral')}</span></button>`).join('');
    root.innerHTML=`${pageHead('Question intelligence','Question bank','Review curriculum questions and locally authored items used by the examination engine.',`<button class="${btnPrimary}" data-question-create>${icon(I.plus,'size-4')} Add question</button>`)}
      <div class="mb-4 grid gap-3 sm:grid-cols-2"><select id="question-subject-filter" class="${field}"><option value="all">All subjects</option>${data.subjectCatalog.map(s=>`<option value="${esc(s.code)}" ${subject===s.code?'selected':''}>${esc(s.label)}</option>`).join('')}</select><div class="flex overflow-x-auto rounded-lg border border-neutral-300 bg-white p-1">${['all','single','multi','boolean','fill'].map(x=>`<button class="min-h-9 whitespace-nowrap rounded-md px-3 text-xs font-semibold ${type===x?'bg-black text-white':'hover:bg-neutral-100'}" data-question-type="${x}">${x}</button>`).join('')}</div></div><section class="${card} overflow-hidden">${questions.length?responsiveTable(['Question','Subject','Levels','Type',''],rows,cards):empty('No matching questions','Change the current filters or add a custom question.')}</section>`;
  }

  function reportsPage() {
    const view=['overview','exams','students','placements','integrity'].includes(qs().get('view'))?qs().get('view'):'overview';
    const tabs=[['overview','Overview'],['exams','Exams'],['students','Students'],['placements','Placements'],['integrity','Integrity']];
    const submitted=Store.getAttempts().filter(a=>a.submittedAt);
    let content='';
    if(view==='overview') content=`<section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">${metric('Submissions',submitted.filter(a=>!a.rewriteArchivedAt).length,'current completed attempts')}${metric('Average',`${mean(submitted.filter(a=>!a.rewriteArchivedAt).map(a=>a.score))}%`,'current attempt average')}${metric('Integrity',`${mean(submitted.filter(a=>!a.rewriteArchivedAt).map(a=>a.integrityScore??100))}%`,'browser signal score')}${metric('Previous attempts',submitted.filter(a=>a.rewriteArchivedAt).length,'preserved rewrite history')}</section>`;
    if(view==='exams') content=`<section class="${card} overflow-hidden">${examTableRows(Store.listSessions())}</section>`;
    if(view==='students') { const students=Store.listUsers().filter(u=>u.role==='student'); content=`<section class="${card} overflow-hidden">${responsiveTable(['Student','Attempts','Average','Integrity',''],students.map(u=>{const rows=attemptsForUser(u).filter(a=>a.submittedAt&&!a.rewriteArchivedAt);return`<tr><td class="px-4 py-3"><button class="font-semibold" data-user-detail="${esc(u.id)}">${esc(u.fullName)}</button></td><td class="px-4 py-3">${rows.length}</td><td class="px-4 py-3">${mean(rows.map(a=>a.score))}%</td><td class="px-4 py-3">${mean(rows.map(a=>a.integrityScore??100))}%</td><td class="px-4 py-3 text-right"><button class="${iconBtn}" data-user-detail="${esc(u.id)}">${icon(I.more)}</button></td></tr>`}).join(''),students.map(u=>`<button class="flex w-full items-center gap-3 p-4 text-left" data-user-detail="${esc(u.id)}"><span class="grid size-10 place-items-center rounded-xl bg-neutral-100 text-xs font-bold">${esc(initials(u.fullName))}</span><span class="flex-1"><strong class="text-sm">${esc(u.fullName)}</strong><span class="block text-xs text-neutral-500">${attemptsForUser(u).length} attempt records</span></span>${icon(I.more,'size-4')}</button>`).join(''))}</section>`; }
    if(view==='placements') content=`<section class="${card} p-5"><h3 class="font-display text-lg font-extrabold">Qualifier placements</h3><div class="mt-4 grid gap-3">${submitted.filter(a=>a.placement&&!a.rewriteArchivedAt).map(a=>`<button class="flex items-center gap-3 rounded-xl border border-neutral-200 p-4 text-left hover:bg-neutral-50" data-attempt-detail="${esc(a.attemptHash)}"><span class="flex-1"><strong class="block text-sm">${esc(a.studentName)}</strong><span class="text-xs text-neutral-500">${esc(a.sessionTitle)}</span></span>${badge(a.placement.assignedTrack,'neutral')}<strong class="text-sm">${a.placement.confidence}%</strong></button>`).join('')||'<p class="text-sm text-neutral-500">No qualifier results yet.</p>'}</div></section>`;
    if(view==='integrity') { const events=submitted.flatMap(a=>(a.integrityEvents||[]).map(ev=>({attempt:a,event:ev}))).sort((a,b)=>b.event.at-a.event.at); content=`<section class="${card} overflow-hidden"><div class="border-b border-neutral-200 p-5"><h3 class="font-display text-lg font-extrabold">Integrity event log</h3><p class="mt-1 text-xs text-neutral-500">Every event remains linked to the exact student attempt and examination.</p></div><div class="divide-y divide-neutral-100">${events.map(({attempt:a,event:ev})=>`<button class="flex w-full items-start gap-3 p-4 text-left hover:bg-neutral-50" data-attempt-detail="${esc(a.attemptHash)}"><span class="mt-1 size-2 shrink-0 rounded-full ${['window-blur','clipboard-copy','clipboard-paste','tab-hidden'].includes(ev.type)?'bg-red-500':'bg-amber-500'}"></span><span class="min-w-0 flex-1"><strong class="block text-sm">${esc(a.studentName)} · ${esc(ev.type)}</strong><span class="mt-1 block text-xs text-neutral-500">${esc(a.sessionTitle)} · ${esc(formatDate(ev.at))}</span></span></button>`).join('')||'<p class="p-5 text-sm text-neutral-500">No integrity events recorded.</p>'}</div></section>`; }
    root.innerHTML=`${pageHead('Academic intelligence','Reports','Exam, student, placement and integrity records share the same attempt relationships.')}<nav class="mb-5 flex overflow-x-auto rounded-xl border border-neutral-200 bg-white p-1" aria-label="Report views">${tabs.map(([key,name])=>`<a href="${href('reports',{view:key})}" class="min-h-9 whitespace-nowrap rounded-lg px-3 py-2 text-xs font-semibold ${view===key?'bg-black text-white':'text-neutral-600 hover:bg-neutral-100'}">${name}</a>`).join('')}</nav>${content}`;
  }

  function settingsPage() {
    root.innerHTML=`${pageHead('Workspace','Settings','Manage browser-local prototype records. Production authentication, authorization and durable storage still require a backend.')}<section class="${card} overflow-hidden"><div class="border-b border-neutral-200 p-5"><h3 class="font-display text-lg font-extrabold">Local data</h3></div><div class="divide-y divide-neutral-100">${[['Exam sessions',Store.listSessions().length,'sessions'],['Candidate attempts',Store.getAttempts().length,'attempts'],['WhatsApp groups',Store.listWhatsAppGroups().length,'groups'],['Custom questions',Store.listCustomQuestions().length,'questions']].map(([name,count,key])=>`<div class="flex items-center justify-between gap-4 p-4"><div><strong class="text-sm">${name}</strong><p class="mt-1 text-xs text-neutral-500">${count} stored</p></div><button class="${btnSecondary}" data-clear-local="${key}">Clear</button></div>`).join('')}<div class="flex items-center justify-between gap-4 p-4"><div><strong class="text-sm text-red-700">Reset entire prototype</strong><p class="mt-1 text-xs text-neutral-500">Sessions, attempts, users, classes, groups and local question changes.</p></div><button class="${btnDanger}" data-reset-all>Reset all</button></div></div></section>`;
  }

  function userDetail(userId) {
    const user=Store.listUsers().find(u=>u.id===userId); if(!user) return toast('User not found.','danger');
    const attempts=attemptsForUser(user).sort((a,b)=>(b.submittedAt||b.startedAt||0)-(a.submittedAt||a.startedAt||0)); const done=attempts.filter(a=>a.submittedAt&&!a.rewriteArchivedAt);
    openDialog(`${modalHeader('Student relationship',user.fullName,`${user.id} · ${classFor(user.classId)?.name||user.role}`)}<div class="p-5 sm:p-6"><div class="grid grid-cols-2 gap-3 sm:grid-cols-4">${[['Status',user.status],['Attempts',attempts.length],['Average',done.length?`${mean(done.map(a=>a.score))}%`:'—'],['Integrity',done.length?`${mean(done.map(a=>a.integrityScore??100))}%`:'—']].map(([k,v])=>`<div class="rounded-xl bg-neutral-50 p-3"><span class="text-xs text-neutral-500">${k}</span><strong class="mt-1 block text-sm">${esc(v)}</strong></div>`).join('')}</div><div class="mt-6 flex flex-wrap gap-2"><button class="${btnSecondary}" data-user-edit="${esc(user.id)}">${icon(I.edit,'size-4')} Edit user</button><button class="${btnSecondary}" data-user-toggle="${esc(user.id)}" data-next-status="${user.status==='active'?'inactive':'active'}">${user.status==='active'?'Suspend':'Activate'}</button></div><div class="mt-6"><div class="flex items-center justify-between"><h3 class="font-display text-lg font-extrabold">Exam history</h3><span class="text-xs text-neutral-500">Exact studentHash relationship</span></div><div class="mt-3 divide-y divide-neutral-100 rounded-xl border border-neutral-200">${attempts.length?attempts.map(a=>`<button class="flex w-full items-center gap-3 p-4 text-left hover:bg-neutral-50" data-attempt-detail="${esc(a.attemptHash)}"><span class="min-w-0 flex-1"><strong class="block truncate text-sm">${esc(a.sessionTitle)}</strong><span class="mt-1 block text-xs text-neutral-500">${a.submittedAt?`${a.score??0}% · Integrity ${a.integrityScore??100}%`:'In progress'}${a.rewriteArchivedAt?' · Previous attempt':''}</span></span>${badge(a.rewriteArchivedAt?'previous':a.submittedAt?'submitted':'in progress',a.rewriteArchivedAt?'neutral':a.submittedAt?'emerald':'amber')}</button>`).join(''):'<p class="p-4 text-sm text-neutral-500">No exam activity for this identity.</p>'}</div></div></div>`);
  }

  function attemptDetail(attemptHash) {
    const attempt=Store.getAttempts().find(a=>a.attemptHash===attemptHash); if(!attempt) return toast('Attempt record not found.','danger');
    const session=Store.findSessionById(attempt.sessionId); const events=attempt.integrityEvents||[];
    openDialog(`${modalHeader('Attempt audit',attempt.studentName||'Candidate',`${attempt.sessionTitle} · ${attempt.sessionId}`)}<div class="p-5 sm:p-6"><div class="grid grid-cols-2 gap-3 sm:grid-cols-4">${[['Status',attempt.rewriteArchivedAt?'Previous':attempt.submittedAt?'Submitted':'In progress'],['Score',attempt.submittedAt?`${attempt.score??0}%`:'—'],['Integrity',`${attempt.integrityScore??100}%`],['Events',events.length]].map(([k,v])=>`<div class="rounded-xl bg-neutral-50 p-3"><span class="text-xs text-neutral-500">${k}</span><strong class="mt-1 block text-sm">${esc(v)}</strong></div>`).join('')}</div>${attempt.rewriteArchivedAt?`<div class="mt-4">${alertMarkup('This is a preserved previous submission. A rewrite was authorized without deleting the original score or proctor log.','info')}</div>`:''}<section class="mt-6"><h3 class="font-display text-lg font-extrabold">Integrity / proctor log</h3><div class="mt-3 max-h-72 divide-y divide-neutral-100 overflow-y-auto rounded-xl border border-neutral-200">${events.length?events.map(ev=>`<div class="flex items-start gap-3 p-3"><span class="mt-1 size-2 shrink-0 rounded-full bg-amber-500"></span><div><strong class="text-sm">${esc(ev.type)}</strong><p class="mt-1 text-xs text-neutral-500">${esc(formatDate(ev.at))}${ev.seconds?` · ${Number(ev.seconds).toFixed(1)} sec`:''}</p></div></div>`).join(''):'<p class="p-4 text-sm text-neutral-500">No integrity exceptions recorded for this attempt.</p>'}</div></section><div class="mt-6 flex flex-wrap gap-2">${!attempt.submittedAt?`<button class="${btnDanger}" data-reset-unfinished data-session-id="${esc(attempt.sessionId)}" data-candidate-hash="${esc(attempt.candidateHash)}">Reset unfinished attempt</button>`:!attempt.rewriteArchivedAt?`<button class="${btnDanger}" data-authorize-rewrite data-session-id="${esc(attempt.sessionId)}" data-candidate-hash="${esc(attempt.candidateHash)}">Authorize rewrite</button>`:''}${session?`<button class="${btnSecondary}" data-exam-detail="${esc(session.id)}">Open exam</button>`:''}</div></div>`);
  }

  function examDetail(sessionId) {
    const s=Store.findSessionById(sessionId); if(!s) return toast('Exam not found.','danger');
    const attempts=Store.attemptsForSession(s.id).sort((a,b)=>(b.submittedAt||b.startedAt||0)-(a.submittedAt||a.startedAt||0)); const activeAttempts=attempts.filter(a=>!a.rewriteArchivedAt); const submitted=activeAttempts.filter(a=>a.submittedAt); const link=directExamLink(s); const camera=Proctor.getAdminPolicy(s.id).cameraRequired;
    openDialog(`${modalHeader('Exam management',s.title,`${s.classLevel} · ${s.classGroup} · ${Store.getModeLabel(s.mode)}`)}<div class="p-5 sm:p-6"><div class="grid gap-4 lg:grid-cols-[220px_minmax(0,1fr)]"><div><div class="rounded-2xl border border-neutral-200 bg-neutral-50 p-4"><div id="exam-detail-qr" class="mx-auto max-w-44 rounded-xl bg-white p-3"></div><p class="mt-3 text-center text-xs font-semibold text-neutral-500">Scan to open this exam</p></div></div><div class="grid content-start gap-3">${examIdLabel(s)}<div class="grid grid-cols-2 gap-3 sm:grid-cols-4">${[['Questions',s.questionCount],['Duration',Store.durationLabel(s.durationSeconds)],['Attempts',activeAttempts.length],['Camera',camera?'Required':'Off']].map(([k,v])=>`<div class="rounded-xl border border-neutral-200 p-3"><span class="text-xs text-neutral-500">${k}</span><strong class="mt-1 block text-sm">${esc(v)}</strong></div>`).join('')}</div><div class="flex flex-wrap gap-2"><button class="${btnPrimary}" data-exam-edit="${esc(s.id)}">${icon(I.edit,'size-4')} Edit settings</button><button class="${btnSecondary}" data-exam-toggle="${esc(s.id)}" data-next-status="${s.status==='closed'?'open':'closed'}">${s.status==='closed'?'Reopen exam':'Close exam'}</button><button class="${btnSecondary}" data-exam-duplicate="${esc(s.id)}">Duplicate</button><button class="${btnDanger}" data-exam-delete="${esc(s.id)}">Delete</button></div></div></div><section class="mt-7"><div class="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between"><div><h3 class="font-display text-lg font-extrabold">Students & attempts</h3><p class="mt-1 text-xs text-neutral-500">Scores and proctor logs are linked directly to this exam and the stored student identity.</p></div><span class="text-xs font-semibold text-neutral-500">${submitted.length} submitted · ${activeAttempts.filter(a=>!a.submittedAt).length} active · ${attempts.filter(a=>a.rewriteArchivedAt).length} previous</span></div><div class="mt-3 divide-y divide-neutral-100 rounded-xl border border-neutral-200">${attempts.length?attempts.map(a=>`<button class="flex w-full items-center gap-3 p-4 text-left hover:bg-neutral-50" data-attempt-detail="${esc(a.attemptHash)}"><span class="grid size-9 shrink-0 place-items-center rounded-lg bg-neutral-100 text-xs font-bold">${esc(initials(a.studentName))}</span><span class="min-w-0 flex-1"><strong class="block truncate text-sm">${esc(a.studentName||'Candidate')}</strong><span class="mt-1 block text-xs text-neutral-500">${a.submittedAt?`Score ${a.score??0}% · Integrity ${a.integrityScore??100}% · ${(a.integrityEvents||[]).length} log event(s)`:`In progress · ${Math.ceil(a.remainingSeconds??0)} sec remaining`}${a.rewriteArchivedAt?' · Previous attempt':''}</span></span>${badge(a.rewriteArchivedAt?'previous':a.submittedAt?'submitted':'in progress',a.rewriteArchivedAt?'neutral':a.submittedAt?'emerald':'amber')}</button>`).join(''):'<p class="p-5 text-sm text-neutral-500">No candidate attempts yet.</p>'}</div></section></div>`);
    renderQr('#exam-detail-qr',link);
  }

  const availableQuestionCount=(draft)=>data.questions.filter(q=>q.levels?.includes(draft.classLevel)&&q.examModes?.includes(draft.mode)&&(draft.mode==='qualifier'?draft.subjects.includes(q.subjectCode):draft.subjects.includes(q.subjectCode))).length;
  const wizardSubjects=(draft)=>data.subjectCatalog.filter(s=>s.levels.includes(draft.classLevel)&&data.questions.some(q=>q.subjectCode===s.code&&q.levels.includes(draft.classLevel)&&q.examModes.includes(draft.mode)));
  const initWizard=()=>({mode:'qualifier',classLevel:'SS1',classGroup:'Qualifier',subjects:['q-eng','q-math','q-bst','q-social'],placementTracks:[...Store.TRACKS],durationSeconds:1800,questionCount:10,status:'open',title:'',instructions:'',integrityPolicy:{focusMonitoring:true,fullscreenPrompt:true,clipboardGuard:true,warnAfter:2},cameraRequired:false});
  function examWizard(step=1) {
    if(!wizard) wizard=initWizard(); step=Math.min(5,Math.max(1,Number(step)||1));
    if(wizard.mode==='qualifier'){wizard.classLevel='SS1';wizard.classGroup='Qualifier';}
    if(wizard.mode==='waec')wizard.classLevel='SS3';
    const available=availableQuestionCount(wizard),maxQuestions=150; wizard.questionCount=Math.min(150,Math.max(5,wizard.questionCount));
    const steps=['Scope','Coverage','Paper','Integrity','Review']; let body='';
    if(step===1) body=`<div class="grid gap-5"><div><p class="${label}">Exam type</p><div class="mt-2 grid gap-2 sm:grid-cols-2">${Object.entries(MODES).map(([key,name])=>`<button type="button" class="rounded-xl border p-4 text-left transition ${wizard.mode===key?'border-black bg-black text-white':'border-neutral-200 hover:bg-neutral-50'}" data-wizard-mode="${key}"><strong class="block text-sm">${name}</strong><span class="mt-1 block text-xs ${wizard.mode===key?'text-neutral-300':'text-neutral-500'}">${key==='qualifier'?'SS1 placement across foundational domains.':key==='mixed'?'One paper across multiple subjects.':key==='single'?'Focused class assessment.':'SS3 subject practice.'}</span></button>`).join('')}</div></div><div><p class="${label}">Class level</p><div class="mt-2 grid grid-cols-3 gap-2">${['SS1','SS2','SS3'].map(x=>`<button class="${wizard.classLevel===x?'bg-black text-white':'border border-neutral-300 bg-white text-neutral-800'} min-h-10 rounded-lg text-sm font-semibold disabled:opacity-30" data-wizard-level="${x}" ${wizard.mode==='qualifier'&&x!=='SS1'||wizard.mode==='waec'&&x!=='SS3'?'disabled':''}>${x}</button>`).join('')}</div></div><div><p class="${label}">Class group</p><div class="mt-2 flex flex-wrap gap-2">${['Qualifier','Science','Arts','Social Science','General'].map(x=>`<button class="min-h-10 rounded-lg border px-3 text-sm font-semibold ${wizard.classGroup===x?'border-black bg-black text-white':'border-neutral-300 bg-white'}" data-wizard-group="${esc(x)}">${esc(x)}</button>`).join('')}</div></div></div>`;
    if(step===2) body=`<div class="grid gap-5">${wizard.mode==='qualifier'?`<div><p class="${label}">Eligible placement tracks</p><div class="mt-2 grid gap-2 sm:grid-cols-3">${Store.TRACKS.map(x=>`<button class="rounded-xl border p-4 text-left ${wizard.placementTracks.includes(x)?'border-black bg-neutral-100':'border-neutral-200'}" data-wizard-track="${esc(x)}"><strong class="text-sm">${esc(x)}</strong></button>`).join('')}</div></div>`:''}<div><p class="${label}">Subject coverage</p><div class="mt-2 grid gap-2 sm:grid-cols-2">${wizardSubjects(wizard).map(s=>`<button class="rounded-xl border p-4 text-left ${wizard.subjects.includes(s.code)?'border-black bg-neutral-100':'border-neutral-200'}" data-wizard-subject="${esc(s.code)}"><strong class="text-sm">${esc(s.label)}</strong><span class="mt-1 block text-xs text-neutral-500">${esc(s.code)}</span></button>`).join('')}</div></div></div>`;
    if(step===3) body=`<div class="grid gap-7"><div><div class="flex items-center justify-between gap-3"><label for="duration-range" class="${label}">Duration</label><strong id="duration-value" class="rounded-full bg-neutral-100 px-3 py-1 text-xs">${esc(Store.durationLabel(wizard.durationSeconds))}</strong></div><input id="duration-range" type="range" min="30" max="10800" step="30" value="${wizard.durationSeconds}" class="mt-4 h-2 w-full cursor-pointer appearance-none rounded-lg bg-neutral-200 accent-black"><div class="mt-2 flex justify-between text-xs text-neutral-500"><span>30 sec</span><span>3 hrs</span></div></div><div><div class="flex items-center justify-between gap-3"><label for="question-count-range" class="${label}">Total questions</label><strong id="question-count-value" class="rounded-full bg-neutral-100 px-3 py-1 text-xs">${wizard.questionCount}</strong></div><input id="question-count-range" type="range" min="5" max="150" step="1" value="${wizard.questionCount}" class="mt-4 h-2 w-full cursor-pointer appearance-none rounded-lg bg-neutral-200 accent-black"><div class="mt-2 flex justify-between text-xs text-neutral-500"><span>Minimum 5</span><span>Maximum 150</span></div><p class="mt-2 text-xs ${available<wizard.questionCount?'font-semibold text-red-700':'text-neutral-500'}">${available} matching question(s) are currently available for this configuration.</p></div><label><span class="${label}">Candidate instruction <span class="font-normal text-neutral-400">optional</span></span><textarea id="wizard-instructions" class="${field} mt-2 min-h-24" maxlength="140" placeholder="What candidates should know before the timer starts">${esc(wizard.instructions)}</textarea></label></div>`;
    if(step===4) body=`<div class="grid gap-3"><p class="text-sm leading-6 text-neutral-600">These controls record browser integrity signals. Camera video stays local in this prototype and is never recorded or uploaded.</p>${[['focusMonitoring','Monitor tab/window changes'],['fullscreenPrompt','Prompt fullscreen'],['clipboardGuard','Block clipboard actions']].map(([key,name])=>`<label class="flex min-h-16 items-center justify-between gap-4 rounded-xl border border-neutral-200 p-4"><span><strong class="block text-sm">${name}</strong></span><input data-integrity-policy="${key}" type="checkbox" class="size-5 rounded border-neutral-300 text-black focus:ring-black" ${wizard.integrityPolicy[key]?'checked':''}></label>`).join('')}<label class="flex min-h-20 items-center justify-between gap-4 rounded-xl border border-neutral-200 p-4"><span class="min-w-0"><strong class="block text-sm">Require candidate camera</strong><span class="mt-1 block text-xs leading-5 text-neutral-500">Candidate must grant camera access before the exam can start or resume.</span></span><input data-proctor-camera type="checkbox" class="size-5 rounded border-neutral-300 text-black focus:ring-black" ${wizard.cameraRequired?'checked':''}></label><label><span class="${label}">Warn after integrity events</span><input id="warn-after" type="number" min="1" max="10" class="${field} mt-2" value="${wizard.integrityPolicy.warnAfter}"></label><div><p class="${label}">Initial status</p><div class="mt-2 grid grid-cols-3 gap-2">${['open','draft','closed'].map(x=>`<button class="min-h-10 rounded-lg border text-sm font-semibold ${wizard.status===x?'border-black bg-black text-white':'border-neutral-300'}" data-wizard-status="${x}">${x}</button>`).join('')}</div></div></div>`;
    if(step===5) { const title=wizard.title||`${wizard.classLevel} ${wizard.mode==='qualifier'?'Placement Qualifier':'Assessment'}`; body=`<div class="grid gap-4"><label><span class="${label}">Exam title</span><input id="wizard-title" class="${field} mt-2" maxlength="72" value="${esc(title)}"></label><div class="grid gap-3 sm:grid-cols-2"><div class="rounded-xl bg-neutral-50 p-4"><span class="text-xs text-neutral-500">Audience</span><strong class="mt-1 block text-sm">${esc(wizard.classLevel)} · ${esc(wizard.classGroup)}</strong></div><div class="rounded-xl bg-neutral-50 p-4"><span class="text-xs text-neutral-500">Paper</span><strong class="mt-1 block text-sm">${wizard.questionCount} questions · ${esc(Store.durationLabel(wizard.durationSeconds))}</strong></div><div class="rounded-xl bg-neutral-50 p-4"><span class="text-xs text-neutral-500">Camera</span><strong class="mt-1 block text-sm">${wizard.cameraRequired?'Required':'Off'}</strong></div><div class="rounded-xl bg-neutral-50 p-4"><span class="text-xs text-neutral-500">Question matches</span><strong class="mt-1 block text-sm">${available} available</strong></div></div>${available<wizard.questionCount?alertMarkup('The selected paper is larger than the available matching question bank.','danger'):alertMarkup('The exam is ready to create. Distribution will expose only a QR code and Exam ID.','success')}</div>`; }
    openDialog(`${modalHeader('Exam builder','Create examination','Five focused steps: scope, coverage, paper, integrity and review.')}<div class="p-5 sm:p-6"><div class="grid grid-cols-5 gap-1">${steps.map((name,index)=>`<div class="min-w-0 text-center"><span class="mx-auto grid size-8 place-items-center rounded-full text-xs font-bold ${index+1<=step?'bg-black text-white':'bg-neutral-100 text-neutral-500'}">${index+1}</span><span class="mt-1 hidden truncate text-[10px] font-semibold text-neutral-500 sm:block">${name}</span></div>`).join('')}</div><div class="mt-6">${body}</div><div class="mt-7 flex items-center justify-between gap-3"><button class="${btnSecondary}" data-wizard-prev data-step="${step}" ${step===1?'disabled':''}>${icon(I.back,'size-4')} Back</button><button class="${btnPrimary}" data-wizard-next data-step="${step}" ${step===3&&available<5?'disabled':''}>${step===5?'Create exam':`Continue ${icon(I.arrow,'size-4')}`}</button></div></div>`,'max-w-4xl');
  }

  function examCreated(session) {
    const link=directExamLink(session);
    openDialog(`${modalHeader('Exam created','Distribution ready','No raw candidate URL is shown in the admin console.')}<div class="p-5 text-center sm:p-7"><div id="created-exam-qr" class="mx-auto max-w-52 rounded-2xl border border-neutral-200 bg-white p-4"></div><div class="mx-auto mt-5 max-w-sm">${examIdLabel(session)}</div><div class="mt-6 flex flex-col justify-center gap-2 sm:flex-row"><button class="${btnPrimary}" data-exam-detail="${esc(session.id)}">Manage exam</button><button class="${btnSecondary}" data-close-dialog>Done</button></div></div>`,'max-w-xl'); renderQr('#created-exam-qr',link);
  }

  function examEdit(sessionId) {
    const s=Store.findSessionById(sessionId); if(!s)return toast('Exam not found.','danger'); const attempts=Store.attemptsForSession(s.id).filter(a=>!a.rewriteArchivedAt); const structuralLocked=attempts.length>0; const available=availableQuestionCount(s); const camera=Proctor.getAdminPolicy(s.id).cameraRequired;
    openDialog(`${modalHeader('Exam settings','Edit examination',structuralLocked?'Candidates have started this exam. Paper shape is locked; delivery and integrity settings remain editable.':'No candidate has started yet, so the paper shape can still be updated.')}<form id="exam-edit-form" data-session-id="${esc(s.id)}" class="grid gap-5 p-5 sm:p-6"><label><span class="${label}">Exam title</span><input id="exam-edit-title" class="${field} mt-2" value="${esc(s.title)}" maxlength="72"></label><div class="grid gap-4 sm:grid-cols-2"><label><span class="${label}">Duration (seconds)</span><input id="exam-edit-duration" type="number" min="30" max="10800" step="30" class="${field} mt-2" value="${s.durationSeconds}" ${structuralLocked?'disabled':''}></label><label><span class="${label}">Question count</span><input id="exam-edit-count" type="number" min="5" max="150" class="${field} mt-2" value="${s.questionCount}" ${structuralLocked?'disabled':''}></label></div><label><span class="${label}">Candidate instruction</span><textarea id="exam-edit-instructions" class="${field} mt-2 min-h-24" maxlength="140">${esc(s.instructions||'')}</textarea></label><div class="grid gap-3 sm:grid-cols-2"><label><span class="${label}">Status</span><select id="exam-edit-status" class="${field} mt-2">${['open','draft','closed'].map(x=>`<option value="${x}" ${s.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span class="${label}">Warn after events</span><input id="exam-edit-warn" type="number" min="1" max="10" class="${field} mt-2" value="${s.integrityPolicy.warnAfter}"></label></div><label class="flex min-h-16 items-center justify-between gap-4 rounded-xl border border-neutral-200 p-4"><span><strong class="block text-sm">Require candidate camera</strong><span class="mt-1 block text-xs text-neutral-500">Applies to QR and manual Exam ID entry.</span></span><input id="exam-edit-camera" type="checkbox" class="size-5 rounded border-neutral-300 text-black focus:ring-black" ${camera?'checked':''}></label><div class="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><button type="button" class="${btnSecondary}" data-close-dialog>Cancel</button><button type="submit" class="${btnPrimary}">Save settings</button></div></form>`);
  }

  function whatsappDialog(groupId='') {
    const existing=Store.listWhatsAppGroups().find(g=>g.id===groupId)||null, classes=Store.listClasses().filter(c=>c.status==='active');
    openDialog(`${modalHeader('Class communication',existing?'Manage WhatsApp group':'Add WhatsApp group','Paste a WhatsApp invite link, associate it with the intended class, and generate the QR locally.')}<form id="whatsapp-form" data-group-id="${esc(existing?.id||'')}" class="grid gap-5 p-5 sm:p-6"><label><span class="${label}">Class</span><select id="whatsapp-class" class="${field} mt-2" required><option value="">Choose class</option>${classes.map(c=>`<option value="${esc(c.id)}" ${existing?.classId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label><span class="${label}">Group name</span><input id="whatsapp-name" class="${field} mt-2" maxlength="72" value="${esc(existing?.name||'')}" placeholder="SS1 Science Parents"></label><label><span class="${label}">WhatsApp group invite link</span><input id="whatsapp-link" type="url" class="${field} mt-2" value="${esc(existing?.inviteUrl||'')}" placeholder="https://chat.whatsapp.com/..." required></label><div id="whatsapp-error" class="hidden"></div>${existing?`<div class="rounded-2xl border border-neutral-200 bg-neutral-50 p-4"><div id="whatsapp-qr" class="mx-auto max-w-48 rounded-xl bg-white p-3"></div><p class="mt-2 text-center text-xs text-neutral-500">QR for ${esc(existing.name)}</p></div>`:''}<div class="flex flex-col-reverse gap-2 sm:flex-row sm:justify-between"><div>${existing?`<button type="button" class="${btnDanger}" data-whatsapp-delete="${esc(existing.id)}">Delete group</button>`:''}</div><div class="flex flex-col-reverse gap-2 sm:flex-row"><button type="button" class="${btnSecondary}" data-close-dialog>Cancel</button><button type="submit" class="${btnPrimary}">${existing?'Save changes':'Save & generate QR'}</button></div></div></form>`,'max-w-2xl');
    if(existing)renderQr('#whatsapp-qr',existing.inviteUrl);
  }

  function classDialog(classId='') {
    const existing=Store.listClasses().find(c=>c.id===classId)||null;
    openDialog(`${modalHeader('Academic structure',existing?'Edit class':'Create class','Keep class naming and communication associations consistent.')}<form id="class-form" data-class-id="${esc(existing?.id||'')}" class="grid gap-5 p-5 sm:p-6"><div class="grid gap-4 sm:grid-cols-2"><label><span class="${label}">Level</span><select id="class-level" class="${field} mt-2">${['SS1','SS2','SS3'].map(x=>`<option ${existing?.classLevel===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span class="${label}">Stream</span><select id="class-stream" class="${field} mt-2">${['Qualifier','Science','Arts','Social Science','General'].map(x=>`<option ${existing?.stream===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="grid gap-4 sm:grid-cols-2"><label><span class="${label}">Capacity</span><input id="class-capacity" type="number" min="1" max="500" class="${field} mt-2" value="${existing?.capacity||60}"></label><label><span class="${label}">Room</span><input id="class-room" class="${field} mt-2" value="${esc(existing?.room||'')}" placeholder="Science Wing"></label></div><div class="flex justify-end gap-2"><button type="button" class="${btnSecondary}" data-close-dialog>Cancel</button><button class="${btnPrimary}" type="submit">Save class</button></div></form>`,'max-w-2xl');
  }
  function classDetail(classId){const cls=Store.listClasses().find(c=>c.id===classId);if(!cls)return toast('Class not found.','danger');const students=Store.listUsers().filter(u=>u.role==='student'&&u.classId===cls.id),group=Store.whatsAppGroupForClass(cls.id);openDialog(`${modalHeader('Class management',cls.name,`${students.length} students · capacity ${cls.capacity}`)}<div class="p-5 sm:p-6"><div class="grid gap-3 sm:grid-cols-2"><div class="rounded-xl bg-neutral-50 p-4"><span class="text-xs text-neutral-500">Stream</span><strong class="mt-1 block">${esc(cls.stream)}</strong></div><div class="rounded-xl bg-neutral-50 p-4"><span class="text-xs text-neutral-500">Room</span><strong class="mt-1 block">${esc(cls.room||'Not assigned')}</strong></div></div><div class="mt-5 flex flex-wrap gap-2"><button class="${btnPrimary}" data-class-edit="${esc(cls.id)}">${icon(I.edit,'size-4')} Edit class</button><button class="${btnSecondary}" data-whatsapp-${group?'edit':'for-class'}="${esc(group?.id||cls.id)}">${icon(I.whatsapp,'size-4')} ${group?'Manage WhatsApp':'Add WhatsApp group'}</button><button class="${btnDanger}" data-class-delete="${esc(cls.id)}">Delete class</button></div></div>`,'max-w-2xl');}

  function userForm(userId=''){const existing=Store.listUsers().find(u=>u.id===userId)||null;const classes=Store.listClasses().filter(c=>c.status==='active');openDialog(`${modalHeader('Directory',existing?'Edit user':'Add user','Student first and last names form the prototype sign-in identity.')}<form id="user-form" data-user-id="${esc(existing?.id||'')}" class="grid gap-5 p-5 sm:p-6"><label><span class="${label}">Full name</span><input id="user-name" class="${field} mt-2" value="${esc(existing?.fullName||'')}" required></label><div class="grid gap-4 sm:grid-cols-2"><label><span class="${label}">Role</span><select id="user-role" class="${field} mt-2">${['student','teacher','administrator'].map(x=>`<option ${existing?.role===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span class="${label}">Class</span><select id="user-class" class="${field} mt-2"><option value="">No class</option>${classes.map(c=>`<option value="${esc(c.id)}" ${existing?.classId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label></div><label><span class="${label}">Guardian</span><input id="user-guardian" class="${field} mt-2" value="${esc(existing?.guardian||'')}"></label><div class="flex justify-end gap-2"><button type="button" class="${btnSecondary}" data-close-dialog>Cancel</button><button class="${btnPrimary}" type="submit">Save user</button></div></form>`,'max-w-2xl');}

  function questionDetail(id){const q=data.questions.find(item=>item.id===Number(id));if(!q)return toast('Question not found.','danger');openDialog(`${modalHeader('Question bank',`Question ${q.id}`,`${q.subject} · ${q.type}`)}<div class="p-5 sm:p-6"><div class="rounded-xl border border-neutral-200 bg-neutral-50 p-5"><p class="font-semibold leading-7">${esc(q.prompt)}</p>${q.options?`<div class="mt-4 grid gap-2">${q.options.map((option,index)=>`<div class="flex gap-3 rounded-lg border border-neutral-200 bg-white p-3"><span class="grid size-7 shrink-0 place-items-center rounded-md bg-black text-xs font-bold text-white">${String.fromCharCode(65+index)}</span><span class="text-sm text-neutral-700">${esc(option)}</span></div>`).join('')}</div>`:''}</div>${q.custom?`<div class="mt-5 flex gap-2"><button class="${btnDanger}" data-question-delete="${q.id}">Delete custom question</button></div>`:''}</div>`,'max-w-2xl');}
  function questionForm(){openDialog(`${modalHeader('Question authoring','Add question','Create a local question that can participate in compatible exams.')}<form id="question-form" class="grid gap-5 p-5 sm:p-6"><div class="grid gap-4 sm:grid-cols-2"><label><span class="${label}">Subject</span><select id="question-subject" class="${field} mt-2">${data.subjectCatalog.map(s=>`<option value="${esc(s.code)}">${esc(s.label)}</option>`).join('')}</select></label><label><span class="${label}">Type</span><select id="question-kind" class="${field} mt-2"><option value="single">Single choice</option><option value="boolean">True / False</option><option value="fill">Fill</option></select></label></div><label><span class="${label}">Question</span><textarea id="question-prompt" class="${field} mt-2 min-h-28" required></textarea></label><div id="question-options" class="grid grid-cols-2 gap-2">${['A','B','C','D'].map(x=>`<input class="${field}" data-option-input placeholder="${x}. Option">`).join('')}</div><label><span class="${label}">Class levels</span><select id="question-level" class="${field} mt-2"><option>SS1</option><option selected>SS2</option><option>SS3</option></select></label><div class="flex justify-end gap-2"><button type="button" class="${btnSecondary}" data-close-dialog>Cancel</button><button class="${btnPrimary}" type="submit">Add question</button></div></form>`,'max-w-2xl');}

  function notificationsDialog(){const drafts=Store.listSessions().filter(s=>s.status==='draft'),active=Store.getAttempts().filter(a=>a.startedAt&&!a.submittedAt);openDialog(`${modalHeader('Activity centre','Notifications','Operational items derived from current browser-local records.')}<div class="grid gap-3 p-5 sm:p-6">${drafts.length?alertMarkup(`${drafts.length} draft exam(s) need publishing or review.`,'warning'):''}${active.length?alertMarkup(`${active.length} attempt(s) are currently in progress.`,'info'):''}${!drafts.length&&!active.length?alertMarkup('No draft exams or active attempts need attention.','success'):''}</div>`,'max-w-xl');}

  async function render(){alertHost.className='hidden';const page=currentPage();chrome(page);await hydrateUserHashes();({overview:overviewPage,users:usersPage,exams:examsPage,classes:classesPage,questions:questionsPage,reports:reportsPage,settings:settingsPage}[page])();root.focus({preventScroll:true});window.initFlowbite?.();}

  function validateWizardStep(step){if(step===2){if((wizard.mode==='single'||wizard.mode==='waec')&&wizard.subjects.length!==1)throw new Error('Choose one subject.');if(wizard.mode==='mixed'&&wizard.subjects.length<2)throw new Error('Choose at least two subjects.');if(wizard.mode==='qualifier'&&!wizard.subjects.length)throw new Error('Choose qualifier subjects.');if(wizard.mode==='qualifier'&&!wizard.placementTracks.length)throw new Error('Choose at least one placement track.');}if(step===3){const available=availableQuestionCount(wizard);if(available<5)throw new Error('At least five matching questions are required.');if(wizard.questionCount>available)throw new Error(`Only ${available} matching questions are available. Reduce the total question count before continuing.`);}}

  document.addEventListener('click', async (event) => {
    const route=event.target.closest('[data-admin-route]');if(route){event.preventDefault();mobileNavDialog?.close();navigate(route.dataset.adminRoute);return;}
    if(event.target.closest('#mobile-nav-button')){mobileNavDialog.showModal();return;} if(event.target.closest('[data-close-mobile-nav]')){mobileNavDialog.close();return;}
    if(event.target.closest('[data-close-dialog]')){closeDialog();return;} if(event.target.closest('[data-toast-close]')){event.target.closest('.pointer-events-auto')?.remove();return;}
    if(event.target.closest('#admin-quick-create')||event.target.closest('[data-open-exam-wizard]')){wizard=initWizard();examWizard(1);return;}
    if(event.target.closest('#admin-notifications')){notificationsDialog();return;}
    const userRole=event.target.closest('[data-user-role]');if(userRole){navigate('users',{role:userRole.dataset.userRole,q:qs().get('q')||''});return;}
    const examStatus=event.target.closest('[data-exam-status]');if(examStatus){navigate('exams',{status:examStatus.dataset.examStatus});return;}
    const qType=event.target.closest('[data-question-type]');if(qType){navigate('questions',{subject:qs().get('subject')||'all',type:qType.dataset.questionType});return;}
    const userDetailBtn=event.target.closest('[data-user-detail]');if(userDetailBtn){userDetail(userDetailBtn.dataset.userDetail);return;}
    const examDetailBtn=event.target.closest('[data-exam-detail]');if(examDetailBtn){examDetail(examDetailBtn.dataset.examDetail);return;}
    const classDetailBtn=event.target.closest('[data-class-detail]');if(classDetailBtn){classDetail(classDetailBtn.dataset.classDetail);return;}
    const questionDetailBtn=event.target.closest('[data-question-detail]');if(questionDetailBtn){questionDetail(questionDetailBtn.dataset.questionDetail);return;}
    const attemptDetailBtn=event.target.closest('[data-attempt-detail]');if(attemptDetailBtn){attemptDetail(attemptDetailBtn.dataset.attemptDetail);return;}
    if(event.target.closest('[data-user-create]')){userForm();return;} const userEdit=event.target.closest('[data-user-edit]');if(userEdit){userForm(userEdit.dataset.userEdit);return;}
    if(event.target.closest('[data-class-create]')){classDialog();return;} const classEdit=event.target.closest('[data-class-edit]');if(classEdit){classDialog(classEdit.dataset.classEdit);return;}
    if(event.target.closest('[data-question-create]')){questionForm();return;}
    const waCreate=event.target.closest('[data-whatsapp-create]');if(waCreate){whatsappDialog();return;} const waEdit=event.target.closest('[data-whatsapp-edit]');if(waEdit){whatsappDialog(waEdit.dataset.whatsappEdit);return;} const waForClass=event.target.closest('[data-whatsapp-for-class]');if(waForClass){whatsappDialog();queueMicrotask(()=>{document.getElementById('whatsapp-class').value=waForClass.dataset.whatsappForClass;});return;}
    const wizardMode=event.target.closest('[data-wizard-mode]');if(wizardMode){wizard.mode=wizardMode.dataset.wizardMode;wizard.subjects=[];if(wizard.mode==='qualifier'){wizard.classLevel='SS1';wizard.classGroup='Qualifier';wizard.subjects=['q-eng','q-math','q-bst','q-social'];wizard.placementTracks=[...Store.TRACKS];}if(wizard.mode==='waec')wizard.classLevel='SS3';examWizard(1);return;}
    const wizardLevel=event.target.closest('[data-wizard-level]');if(wizardLevel){wizard.classLevel=wizardLevel.dataset.wizardLevel;wizard.subjects=[];examWizard(1);return;}
    const wizardGroup=event.target.closest('[data-wizard-group]');if(wizardGroup){wizard.classGroup=wizardGroup.dataset.wizardGroup;examWizard(1);return;}
    const wizardTrack=event.target.closest('[data-wizard-track]');if(wizardTrack){const value=wizardTrack.dataset.wizardTrack;wizard.placementTracks=wizard.placementTracks.includes(value)?wizard.placementTracks.filter(x=>x!==value):[...wizard.placementTracks,value];examWizard(2);return;}
    const wizardSubject=event.target.closest('[data-wizard-subject]');if(wizardSubject){const value=wizardSubject.dataset.wizardSubject;if(['single','waec'].includes(wizard.mode))wizard.subjects=[value];else wizard.subjects=wizard.subjects.includes(value)?wizard.subjects.filter(x=>x!==value):[...wizard.subjects,value];examWizard(2);return;}
    const wizardStatus=event.target.closest('[data-wizard-status]');if(wizardStatus){wizard.status=wizardStatus.dataset.wizardStatus;examWizard(4);return;}
    if(event.target.closest('[data-wizard-prev]')){const current=Number(event.target.closest('[data-wizard-prev]').dataset.step)||1;examWizard(Math.max(1,current-1));return;}
    const wizardNext=event.target.closest('[data-wizard-next]');if(wizardNext){const step=Number(wizardNext.dataset.step);try{validateWizardStep(step);if(step<5){if(step===4){wizard.integrityPolicy.warnAfter=Math.max(1,Math.min(10,Number(document.getElementById('warn-after')?.value)||2));}examWizard(step+1);return;}wizard.title=document.getElementById('wizard-title')?.value.trim()||wizard.title||`${wizard.classLevel} Assessment`;const created=Store.saveSession({...wizard,placementTracks:wizard.placementTracks,integrityPolicy:wizard.integrityPolicy});Proctor.setAdminPolicy(created.id,{cameraRequired:wizard.cameraRequired});wizard=null;examCreated(created);render();}catch(error){announce(error.message,'danger');}return;}
    const examEditBtn=event.target.closest('[data-exam-edit]');if(examEditBtn){examEdit(examEditBtn.dataset.examEdit);return;}
    const examToggle=event.target.closest('[data-exam-toggle]');if(examToggle){Store.updateSessionStatus(examToggle.dataset.examToggle,examToggle.dataset.nextStatus);toast('Exam status updated.','success');examDetail(examToggle.dataset.examToggle);render();return;}
    const examDuplicate=event.target.closest('[data-exam-duplicate]');if(examDuplicate){const source=Store.findSessionById(examDuplicate.dataset.examDuplicate);if(source){const copy=Store.saveSession({...source,id:undefined,title:`${source.title} copy`.slice(0,72),status:'draft',createdAt:Date.now()});Proctor.setAdminPolicy(copy.id,Proctor.getAdminPolicy(source.id));toast('Exam duplicated as a draft.','success');examDetail(copy.id);render();}return;}
    const examDelete=event.target.closest('[data-exam-delete]');if(examDelete){const id=examDelete.dataset.examDelete;confirmDialog({title:'Delete this examination?',detail:'The session definition will be removed. Existing attempt records remain available in reports for audit history.',confirm:'Delete exam',danger:true,onConfirm:async()=>{Store.deleteSession(id);toast('Exam deleted. Attempt history was preserved.','success');await render();}});return;}
    const reset=event.target.closest('[data-reset-unfinished]');if(reset){const {sessionId,candidateHash}=reset.dataset;confirmDialog({title:'Reset unfinished attempt?',detail:'The candidate can authenticate and start this same exam again. The unfinished state will be cleared.',confirm:'Reset attempt',danger:true,onConfirm:async()=>{Store.resetUnfinishedAttempt(sessionId,candidateHash);toast('Unfinished attempt reset.','success');examDetail(sessionId);}});return;}
    const rewrite=event.target.closest('[data-authorize-rewrite]');if(rewrite){const {sessionId,candidateHash}=rewrite.dataset;confirmDialog({title:'Authorize a rewrite?',detail:'The submitted attempt, score and integrity log will be preserved as a previous attempt. The student may then authenticate and take the exam again.',confirm:'Authorize rewrite',danger:true,onConfirm:async()=>{Store.authorizeRewrite(sessionId,candidateHash);toast('Rewrite authorized. Previous submission preserved.','success');examDetail(sessionId);}});return;}
    const userToggle=event.target.closest('[data-user-toggle]');if(userToggle){Store.updateUserStatus(userToggle.dataset.userToggle,userToggle.dataset.nextStatus);toast('User status updated.','success');await render();userDetail(userToggle.dataset.userToggle);return;}
    const classDelete=event.target.closest('[data-class-delete]');if(classDelete){const id=classDelete.dataset.classDelete;confirmDialog({title:'Delete this class?',detail:'Students remain in the directory, but the class and its associated WhatsApp group will be removed.',confirm:'Delete class',danger:true,onConfirm:async()=>{Store.deleteClass(id);toast('Class removed.','success');await render();}});return;}
    const waDelete=event.target.closest('[data-whatsapp-delete]');if(waDelete){const id=waDelete.dataset.whatsappDelete;confirmDialog({title:'Delete WhatsApp group mapping?',detail:'The invite link and locally generated QR mapping will be removed from this browser.',confirm:'Delete group',danger:true,onConfirm:async()=>{Store.deleteWhatsAppGroup(id);toast('WhatsApp group removed.','success');await render();}});return;}
    const qDelete=event.target.closest('[data-question-delete]');if(qDelete){Store.deleteCustomQuestion(Number(qDelete.dataset.questionDelete));data=await Data.load();closeDialog();toast('Custom question deleted.','success');render();return;}
    const clear=event.target.closest('[data-clear-local]');if(clear){const key=clear.dataset.clearLocal;confirmDialog({title:`Clear ${key}?`,detail:'This affects only browser-local prototype data.',confirm:'Clear data',danger:true,onConfirm:async()=>{if(key==='sessions')Store.clearSessions();if(key==='attempts')Store.clearAttempts();if(key==='groups')Store.listWhatsAppGroups().forEach(g=>Store.deleteWhatsAppGroup(g.id));if(key==='questions')Store.listCustomQuestions().forEach(q=>Store.deleteCustomQuestion(q.id));data=await Data.load();toast('Selected local data cleared.','success');await render();}});return;}
    if(event.target.closest('[data-reset-all]')){confirmDialog({title:'Reset the entire prototype?',detail:'All browser-local sessions, attempts, users, classes, groups and custom questions will be cleared.',confirm:'Reset prototype',danger:true,onConfirm:async()=>{Store.clearPrototypeData();data=await Data.load();toast('Prototype data reset.','success');await render();}});return;}
  });

  document.addEventListener('change',(event)=>{if(event.target.id==='question-subject-filter')navigate('questions',{subject:event.target.value,type:qs().get('type')||'all'});const integrity=event.target.closest('[data-integrity-policy]');if(integrity&&wizard)wizard.integrityPolicy[integrity.dataset.integrityPolicy]=integrity.checked;if(event.target.matches('[data-proctor-camera]')&&wizard)wizard.cameraRequired=event.target.checked;});
  document.addEventListener('input',(event)=>{if(!wizard)return;if(event.target.id==='duration-range'){wizard.durationSeconds=Number(event.target.value);document.getElementById('duration-value').textContent=Store.durationLabel(wizard.durationSeconds);}if(event.target.id==='question-count-range'){wizard.questionCount=Number(event.target.value);document.getElementById('question-count-value').textContent=String(wizard.questionCount);}if(event.target.id==='wizard-instructions')wizard.instructions=event.target.value;});
  let searchTimer=null;document.addEventListener('input',(event)=>{if(event.target.id==='user-search'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>navigate('users',{role:qs().get('role')||'all',q:event.target.value},true),220);}});

  document.addEventListener('submit',async(event)=>{
    if(event.target.id==='exam-edit-form'){event.preventDefault();const id=event.target.dataset.sessionId,s=Store.findSessionById(id),attempts=Store.attemptsForSession(id).filter(a=>!a.rewriteArchivedAt);if(!s)return;const available=availableQuestionCount(s);try{const requestedCount=attempts.length?s.questionCount:Number(document.getElementById('exam-edit-count').value);if(!attempts.length&&requestedCount>available)throw new Error(`Only ${available} matching questions are available for this exam.`);const updated=Store.saveSession({...s,title:document.getElementById('exam-edit-title').value,instructions:document.getElementById('exam-edit-instructions').value,status:document.getElementById('exam-edit-status').value,integrityPolicy:{...s.integrityPolicy,warnAfter:Number(document.getElementById('exam-edit-warn').value)},...(attempts.length?{}:{durationSeconds:Number(document.getElementById('exam-edit-duration').value),questionCount:requestedCount})});Proctor.setAdminPolicy(id,{cameraRequired:document.getElementById('exam-edit-camera').checked});toast('Exam settings updated.','success');examDetail(updated.id);await render();}catch(error){toast(error.message,'danger');}return;}
    if(event.target.id==='whatsapp-form'){event.preventDefault();const errorHost=document.getElementById('whatsapp-error');try{const saved=Store.saveWhatsAppGroup({id:event.target.dataset.groupId||undefined,classId:document.getElementById('whatsapp-class').value,name:document.getElementById('whatsapp-name').value,inviteUrl:document.getElementById('whatsapp-link').value});toast('WhatsApp group saved and QR generated.','success');whatsappDialog(saved.id);await render();}catch(error){errorHost.innerHTML=alertMarkup(error.message,'danger');errorHost.classList.remove('hidden');}return;}
    if(event.target.id==='class-form'){event.preventDefault();try{const level=document.getElementById('class-level').value,stream=document.getElementById('class-stream').value;Store.saveClass({id:event.target.dataset.classId||undefined,classLevel:level,stream,group:stream,name:`${level} ${stream}`,capacity:Number(document.getElementById('class-capacity').value),room:document.getElementById('class-room').value});closeDialog();toast('Class saved.','success');await render();}catch(error){toast(error.message,'danger');}return;}
    if(event.target.id==='user-form'){event.preventDefault();try{const role=document.getElementById('user-role').value,classId=document.getElementById('user-class').value;if(role==='student'&&!classId)throw new Error('Choose a class for the student.');Store.saveUser({id:event.target.dataset.userId||undefined,fullName:document.getElementById('user-name').value,guardian:document.getElementById('user-guardian').value,role,classId});closeDialog();toast('User saved.','success');await render();}catch(error){toast(error.message,'danger');}return;}
    if(event.target.id==='question-form'){event.preventDefault();try{const subjectCode=document.getElementById('question-subject').value,subject=Data.subjectByCode(data,subjectCode),type=document.getElementById('question-kind').value,prompt=document.getElementById('question-prompt').value.trim(),level=document.getElementById('question-level').value;if(!prompt)throw new Error('Write the question stem.');const q={subject:subject?.label||subjectCode,subjectCode,domain:'Custom curriculum practice',label:'Custom question',prompt,type,levels:[level],examModes:['single','mixed','waec']};if(type==='single'){q.options=[...dialog.querySelectorAll('[data-option-input]')].map(input=>input.value.trim()).filter(Boolean);if(q.options.length<2)throw new Error('Add at least two answer options.');}if(type==='boolean')q.options=['True','False'];if(type==='fill')q.fillTemplate=[{text:`${prompt} `},{blank:'answer'}];Store.saveCustomQuestion(q);data=await Data.load();closeDialog();toast('Question added.','success');await render();}catch(error){toast(error.message,'danger');}return;}
  });

  dialog.addEventListener('click',(event)=>{if(event.target===dialog)closeDialog();});
  dialog.addEventListener('cancel',(event)=>{event.preventDefault();closeDialog();});
  document.addEventListener('keydown',(event)=>{if(event.key==='Escape'&&mobileNavDialog?.open)mobileNavDialog.close();});
  window.addEventListener('popstate',()=>render());
  document.getElementById('admin-global-search')?.addEventListener('keydown',(event)=>{if(event.key==='Enter')navigate('users',{q:event.currentTarget.value});});

  renderNav();
  Data.load().then(async(payload)=>{data=payload;await render();}).catch((error)=>{root.innerHTML=`<section class="${card} mx-auto max-w-2xl p-7">${alertMarkup(error.message,'danger')}<h2 class="mt-5 font-display text-2xl font-extrabold">Question data unavailable</h2></section>`;announce(error.message,'danger');});
})();
